def add_bkt(add):
    add('backtracking', 'Enumeră plățile cu stoc și limită', 'Citește n S M și n perechi valoare stoc. Enumeră toate vectorurile de n cantități care plătesc S cu maximum M monede și respectă stocurile. Valorile pozitive distincte. Ordine liberă fără duplicate; fără soluție afișează NU.', 'La nivelul i alegi 0..min(stoc,suma_rămasă//valoare,monede_rămase).', 'n, S, M = map(int, input().split())\na = [tuple(map(int, input().split())) for _ in range(n)]\npath = []\nfound = False\ndef bkt(i, rest, left):\n    global found\n    if i == n:\n        if rest == 0:\n            found = True\n            print(*path)\n        return\n    v, stoc = a[i]\n    for k in range(min(stoc, rest // v, left) + 1):\n        path.append(k)\n        bkt(i + 1, rest - k * v, left - k)\n        path.pop()\nbkt(0, S, M)\nif not found:\n    print("NU")', [('2 4 2\n1 4\n2 2','0 2'),('2 4 4\n1 4\n2 2','0 2\n2 1\n4 0'),('1 3 5\n2 5','NU')], 'Aprofundare', validator='set-lines')
    add('backtracking', 'Toate submulțimile de sumă S', 'Citește numere naturale distincte, apoi S. Afișează indicii de la 1 ai tuturor submulțimilor de sumă S, crescători în fiecare soluție. Ordine liberă; mulțimea vidă este VID, lipsa soluțiilor este NU.', 'Alege includere/excludere și verifică suma după toate elementele.', 'a = list(map(int, input().split()))\nS = int(input())\npath = []\nfound = False\ndef bkt(i, s):\n    global found\n    if i == len(a):\n        if s == S:\n            found = True\n            print(*path if path else ["VID"])\n        return\n    bkt(i + 1, s)\n    path.append(i + 1)\n    bkt(i + 1, s + a[i])\n    path.pop()\nbkt(0, 0)\nif not found:\n    print("NU")', [('1 2 3\n3','3\n1 2'),('0 1\n0','VID\n1'),('2 4\n3','NU')], 'Aplicare', validator='set-lines')
    add('backtracking', 'Anagrame distincte', 'Citește un cuvânt lowercase de 1..6 litere. Afișează toate anagramele distincte lexicografic, una pe linie.', 'Counter evită duplicatele în timpul generării, fără a memora toate permutările.', 'from collections import Counter\ns = input()\nf = Counter(s)\ndef bkt(path):\n    if len(path) == len(s):\n        print(path)\n        return\n    for c in sorted(f):\n        if f[c]:\n            f[c] -= 1\n            bkt(path + c)\n            f[c] += 1\nbkt("")', [('aab','aab\naba\nbaa'),('x','x'),('ab','ab\nba')], 'Aplicare')
    add('backtracking', 'Echipe mixte', 'Citește n m k. Fetele sunt 1..n și băieții n+1..n+m. Enumeră echipele de k persoane cu minimum o fată și un băiat. Indicii cresc în fiecare echipă; ordine liberă a liniilor, fără duplicate. Fără soluție: NU. n+m ≤ 12.', 'Generează combinări și verifică ambele categorii.', 'n, m, k = map(int, input().split())\na = []\nfound = False\ndef bkt(start):\n    global found\n    if len(a) == k:\n        if any(x <= n for x in a) and any(x > n for x in a):\n            print(*a)\n            found = True\n        return\n    for x in range(start, n + m + 1):\n        a.append(x)\n        bkt(x + 1)\n        a.pop()\nbkt(1)\nif not found:\n    print("NU")', [('2 1 2','1 3\n2 3'),('1 1 2','1 2'),('2 0 2','NU')], 'Aplicare', validator='set-lines')
    add('backtracking', 'Numere cu sumă de cifre', 'Citește n s, 1 ≤ n ≤ 4. Afișează crescător numerele de exact n cifre, fără zero inițial, cu suma cifrelor s. Fără soluție: NU.', 'Prima cifră este 1..9, celelalte 0..9. Elimină ramurile cu suma rămasă imposibilă.', 'n, S = map(int, input().split())\nfound = False\ndef bkt(text, rest):\n    global found\n    if len(text) == n:\n        if rest == 0:\n            print(text)\n            found = True\n        return\n    for c in range(1 if not text else 0, 10):\n        if 0 <= rest - c <= 9 * (n - len(text) - 1):\n            bkt(text + str(c), rest - c)\nbkt("", S)\nif not found:\n    print("NU")', [('2 2','11\n20'),('1 0','NU'),('1 9','9')], 'Aplicare')
    add('backtracking', 'Descompuneri în prime', 'Citește 2 ≤ n ≤ 20. Afișează toate descompunerile ca sumă de prime nedescrescătoare, fără duplicate. Termenii pot fi repetați; ordinea liniilor este liberă.', 'Următorul prim începe de la cel precedent, eliminând permutările aceleiași sume.', 'n = int(input())\nprimes = [x for x in range(2, n + 1) if all(x % d for d in range(2, int(x ** .5) + 1))]\na = []\ndef bkt(start, rest):\n    if rest == 0:\n        print(*a)\n        return\n    for i in range(start, len(primes)):\n        if primes[i] <= rest:\n            a.append(primes[i])\n            bkt(i, rest - primes[i])\n            a.pop()\nbkt(0, n)', [('5','2 3\n5'),('4','2 2'),('10','2 2 2 2 2\n2 2 3 3\n2 3 5\n3 7\n5 5')], 'Aprofundare', validator='set-lines')
    add('backtracking', 'Produs cartezian', 'Citește n între 1 și 4, apoi n linii de întregi distincți între -99 și 99, fiecare cu cel mult 5 valori. Enumeră tuplurile care aleg un element din fiecare linie; ordine liberă fără duplicate. Dacă o mulțime este vidă, NU.', 'Nivelul i alege un element din mulțimea i.', 'n = int(input())\na = [list(map(int, input().split())) for _ in range(n)]\npath = []\nfound = False\ndef bkt(i):\n    global found\n    if i == n:\n        found = True\n        print(*path)\n        return\n    for x in a[i]:\n        path.append(x)\n        bkt(i + 1)\n        path.pop()\nbkt(0)\nif not found:\n    print("NU")', [('2\n1 4\n2 6','1 2\n1 6\n4 2\n4 6'),('1\n9','9'),('2\n1\n\n','NU')], 'Aplicare', validator='set-lines')
    add('backtracking', 'Chestionare cu punctaj fix', 'Prima linie n a p, n ≤ 12; a doua are punctajele pozitive. Enumeră grupurile de exact a întrebări cu punctaj total p, folosind indicii de la 1 crescător. Ordine liberă fără duplicate; fără soluții NU.', 'Generează combinări cu un contor de întrebări și suma curentă.', 'n, k, S = map(int, input().split())\na = list(map(int, input().split()))\npath = []\nfound = False\ndef bkt(start, s):\n    global found\n    if len(path) == k:\n        if s == S:\n            print(*path)\n            found = True\n        return\n    for i in range(start, n):\n        path.append(i + 1)\n        bkt(i + 1, s + a[i])\n        path.pop()\nbkt(0, 0)\nif not found:\n    print("NU")', [('4 2 5\n1 4 2 3','1 2\n3 4'),('2 1 7\n1 2','NU'),('3 3 6\n1 2 3','1 2 3')], 'Aplicare', validator='set-lines')
    add('backtracking', 'Deranjamente: scrisorile', 'Citește 1 ≤ n ≤ 6. Enumeră lexicografic permutările 1..n cu valoarea de pe poziția i diferită de i, indicii de la 1. Fiecare permutare reprezintă destinatarii scrisorilor. Fără soluție: NU.', 'La nivelul i exclude valorile folosite și valoarea i.', 'n = int(input())\na = []\nfound = False\ndef bkt():\n    global found\n    if len(a) == n:\n        print(*a)\n        found = True\n        return\n    for x in range(1, n + 1):\n        if x not in a and x != len(a) + 1:\n            a.append(x)\n            bkt()\n            a.pop()\nbkt()\nif not found:\n    print("NU")', [('3','2 3 1\n3 1 2'),('1','NU'),('2','2 1')], 'Aprofundare')
    add('backtracking', 'Echipe cu mărime impară', 'Citește 1 ≤ n ≤ 8. Enumeră submulțimile de mărime impară ale persoanelor 1..n. Indicii sunt crescători în fiecare echipă; ordinea liniilor este liberă.', 'Generează combinări pentru k=1,3,5,... .', 'n = int(input())\na = []\ndef bkt(start, k):\n    if len(a) == k:\n        print(*a)\n        return\n    for x in range(start, n + 1):\n        a.append(x)\n        bkt(x + 1, k)\n        a.pop()\nfor k in range(1, n + 1, 2):\n    bkt(1, k)', [('3','1\n2\n3\n1 2 3'),('2','1\n2'),('1','1')], 'Aplicare', validator='set-lines')
    add('backtracking', 'Enumeră plățile nelimitate', 'Citește monedele pozitive distincte pe prima linie și suma S pe a doua. Afișează toate vectorurile de cantități în ordinea monedelor, câte unul pe linie. Ordinea liniilor este liberă; fără soluție NU.', 'Alege cantitatea fiecărui tip o singură dată; astfel ordinea monedelor plătite nu produce duplicate.', 'a = list(map(int, input().split()))\nS = int(input())\npath = []\nfound = False\ndef bkt(i, rest):\n    global found\n    if i == len(a):\n        if rest == 0:\n            found = True\n            print(*path)\n        return\n    for k in range(rest // a[i] + 1):\n        path.append(k)\n        bkt(i + 1, rest - k * a[i])\n        path.pop()\nbkt(0, S)\nif not found:\n    print("NU")', [('1 2\n4','0 2\n2 1\n4 0'),('2\n3','NU'),('3 5\n0','0 0')], 'Aplicare', validator='set-lines')

